import sys
sys.argv=['cleanup-old-rollouts','--execute']
import os,sys,json,pathlib,time,subprocess
import zlib,base64
PLAN = json.loads(zlib.decompress(base64.b64decode('')))
DELETE = '--execute' in sys.argv
records=PLAN['records']; roots=PLAN['roots'];blocked=[];refs=[]
active=pathlib.Path('/mnt/data/shaoshitong/search-g1-speed-resume5-0553ade-20261012')
assert active.exists()
before=subprocess.check_output(['df','-B1','/mnt/data'],text=True)
for proc in pathlib.Path('/proc').glob('[0-9]*'):
 if int(proc.name)==os.getpid():continue
 try:
  cmd=(proc/'cmdline').read_bytes().replace(b'\0',b' ').decode(errors='replace')
  for root in roots:
   if root in cmd:refs.append({'scope':root,'kind':'process-cmdline','pid':proc.name})
  for fd in (proc/'fd').iterdir():
   try:target=str(fd.resolve())
   except OSError:continue
   for root in roots:
    if target==root or target.startswith(root+'/'):refs.append({'scope':target,'kind':'process-fd','pid':proc.name})
 except (FileNotFoundError,ProcessLookupError):pass
for base in [pathlib.Path('/dataset'),active]:
 for dp,ds,fs in os.walk(base,followlinks=False):
  for n in ds+fs:
   p=pathlib.Path(dp)/n
   if p.is_symlink():
    target=str(p.resolve())
    if any(target==root or target.startswith(root+'/') for root in roots):refs.append({'scope':target,'kind':'asset-alias','path':str(p)})
  ds[:]=[d for d in ds if d not in ['env','cache','.git','site-packages','__pycache__']]
# Check actual live configurations as well as in-memory process paths.
for area in [active/'artifacts',active/'logs',active/'data']:
 for p in area.rglob('*.json'):
  if p.is_file() and not p.is_symlink() and p.stat().st_size<1024*1024:
   txt=p.read_text(errors='replace')
   for root in roots:
    if root in txt:refs.append({'scope':root,'kind':'live-config','path':str(p)})
for r in records:
 p=pathlib.Path(r['path']);root=next((s for s in roots if r['path'].startswith(s+'/')),None)
 assert root and p.suffix=='.pt' and not p.is_symlink()
 rel=p.relative_to(root)
 assert (len(rel.parts)==1 and p.name.startswith('actual-rollout-attempt')) or (len(rel.parts)==4 and rel.parts[:2]==('audit','partial-updates') and rel.parts[2].startswith('attempt_') and rel.parts[3]=='driver.pt')
 if not p.exists():continue
 st=p.stat();assert (st.st_size,st.st_mtime_ns,st.st_ino)==(r['bytes'],r['mtime_ns'],r['inode'])
 if any(r['path']==a['scope'] or r['path'].startswith(a['scope']+'/') for a in refs):blocked.append(r['path'])
if blocked:raise RuntimeError('Active dependency found; no files deleted: '+str(len(blocked)))
deleted=[]
if DELETE:
 for r in records:
  p=pathlib.Path(r['path'])
  if not p.exists():continue
  assert not p.is_symlink();st=p.stat();assert(st.st_size,st.st_mtime_ns,st.st_ino)==(r['bytes'],r['mtime_ns'],r['inode']);p.unlink();deleted.append(r)
print(json.dumps({'epoch':time.time(),'executed':DELETE,'before_df':before,'after_df':subprocess.check_output(['df','-B1','/mnt/data'],text=True),'candidates':len(records),'candidate_allocated_bytes':PLAN['allocated_bytes'],'deleted':deleted,'deleted_allocated_bytes':sum(r['allocated_bytes'] for r in deleted),'blocked':blocked,'references':refs}))
